// Beat [5] — "YubiKeys literally just do this": challenge–response.
// A server sends a random challenge; the YubiKey signs it with its private key;
// the server verifies the signature with the public key.
// Forging is impossible; verifying is trivial.
// (Public-key crypto was introduced earlier; the audience is not all technical.)

private val forgeColor = Color(0xFFE53935)
private val verifyColor = Color(0xFF43A047)

/** Rectangle placeholder for an image asset to be supplied later. */
@Composable
private fun Placeholder(name: String) {
    Box(
        modifier = Modifier
            .size(24.dp)
            .clip(RoundedCornerShape(4.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = name,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

/** One party: a server (public key) or a yubikey (private key). */
@Composable
private fun Actor(name: String, icon: ImageVector?, iconLabel: String, keyIcon: ImageVector, keyLabel: String) {
    Column(
        modifier = Modifier
            .clip(RoundedCornerShape(12.dp))
            .border(1.dp, MaterialTheme.colorScheme.outline, RoundedCornerShape(12.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(10.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        if (icon != null) {
            Icon(imageVector = icon, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(28.dp))
        } else {
            Placeholder(iconLabel)
        }
        Text(name, style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.onSurface)
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            Icon(imageVector = keyIcon, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp))
            Text(keyLabel, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
        }
    }
}

@Composable
private fun Chip(text: String, mono: Boolean = false) {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(6.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(horizontal = 6.dp, vertical = 3.dp)
    ) {
        Text(
            text = text,
            style = MaterialTheme.typography.labelSmall.copy(fontFamily = if (mono) FontFamily.Monospace else null),
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

/** The channel between the two actors: challenge →, ← signature, ✓ verified. */
@Composable
private fun Channel(step: Int) {
    Box(modifier = Modifier.width(220.dp), contentAlignment = Alignment.Center) {
        androidx.compose.animation.AnimatedVisibility(
            visible = step == 1,
            enter = fadeIn() + slideInHorizontally(initialOffsetX = { -it }),
            exit = fadeOut()
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Chip("challenge: 73529", mono = true)
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.size(18.dp)
                )
            }
        }
        androidx.compose.animation.AnimatedVisibility(
            visible = step == 2,
            enter = fadeIn() + slideInHorizontally(initialOffsetX = { it }),
            exit = fadeOut()
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(2.dp)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowLeft,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.size(18.dp)
                    )
                    Chip("sig: 0xA1F3…", mono = true)
                }
                Text("signed: private key", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
        }
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 3,
            enter = fadeIn() + slideInVertically(initialOffsetY = { it / 2 }),
            exit = fadeOut()
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(2.dp)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.Check,
                        contentDescription = null,
                        tint = verifyColor,
                        modifier = Modifier.size(18.dp)
                    )
                    Text("verified", style = MaterialTheme.typography.labelLarge, color = verifyColor, fontWeight = FontWeight.Bold)
                }
                Text("via public key", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
        }
    }
}

@Composable
private fun Verdict(question: String, sub: String, verdict: String, accent: Color) {
    Column(
        modifier = Modifier
            .clip(RoundedCornerShape(10.dp))
            .background(accent.copy(alpha = 0.16f))
            .border(1.dp, accent.copy(alpha = 0.6f), RoundedCornerShape(10.dp))
            .padding(10.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(2.dp)
    ) {
        Text(question, style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.onSurface)
        Text(sub, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
        Text(verdict, style = MaterialTheme.typography.labelLarge, color = accent, fontWeight = FontWeight.Bold)
    }
}

@Composable
private fun Punchline() {
    Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(10.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            Verdict("Forge a signature?", "without the private key", "≈ impossible", forgeColor)
            Verdict("Verify a signature?", "with the public key", "instant · anyone", verifyColor)
        }
        Text(
            text = "Hard to forge · easy to verify",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.primary,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
private fun Scene(step: Int) {
    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            text = "How a YubiKey proves it's you",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Actor("server", Icons.Default.Dns, "server", Icons.Default.LockOpen, "public key")
            Channel(step)
            Actor("yubikey", null, "yubikey", Icons.Default.Lock, "private key")
        }

        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 4,
            enter = fadeIn() + slideInVertically(initialOffsetY = { it / 2 }),
            exit = fadeOut()
        ) {
            Punchline()
        }
    }
}

val challenge by Slide(stepCount = 5, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    Scene(step)
}
