// The concrete device we have: a YubiKey 5C NFC (USB-C). Distinguish it from the
// visually-identical, cheaper "Security Key C NFC" — ours has the QR-like code +
// serial on the back; the cheaper one doesn't. AAGUID confirms the 5-series.
val ourKey by Slide(stepCount = 2, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    Column(
        modifier = Modifier.fillMaxSize().padding(20.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "The one we have: YubiKey 5C NFC",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurface
        )

        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(24.dp)
        ) {
            Image(
                painter = painterResource(Res.drawable.yubikey_exact_model_we_have),
                contentDescription = "Our YubiKey 5C NFC",
                modifier = Modifier
                    .size(width = 220.dp, height = 185.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .border(1.dp, MaterialTheme.colorScheme.onSurfaceVariant, RoundedCornerShape(8.dp)),
                contentScale = ContentScale.Fit
            )
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Fact("Look-alike") {
                    Text(
                        "The cheaper \"Security Key C NFC\" is visually identical — but ours has the QR-like code + serial on the back.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
                Fact("AAGUID") {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            "d7781e5d-e353-46aa-afe2-3ca49f13332a",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier.size(18.dp)
                        )
                        Text(
                            "YubiKey 5C NFC",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
                Fact("Verify") {
                    Text(
                        "yubico.com/genuine",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            }
        }

        // Step 1 — the NFC support pops in (plain styled text, not a button).
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 1,
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
                scaleIn(
                    initialScale = 0.5f,
                    animationSpec = spring(Spring.DampingRatioMediumBouncy, Spring.StiffnessLow)
                )
        ) {
            Text(
                "By the way, it also supports NFC!",
                color = MaterialTheme.colorScheme.primary,
                fontSize = 22.sp,
                fontWeight = FontWeight.Bold,
                fontStyle = FontStyle.Italic,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
private fun Fact(label: String, content: @Composable () -> Unit) {
    Column {
        Text(label, style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
        content()
    }
}
