import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import net.kodein.cup.SLIDE_SIZE_16_9
import net.kodein.cup.Slide
import net.kodein.cup.SlideSpecs

private const val WORD = "hello"
private val chars = WORD.toList()
private val ascii = WORD.map { it.code }
private val bitStrings = ascii.map { it.toString(2).padStart(8, '0') }

/** All 40 bits of "hello" as one continuous string. */
private val helloBits = bitStrings.joinToString("")

/** A fixed pseudo-random 40-bit line (same length as [helloBits]). */
private val randomBits: String = "0111010100110010101101010110100110101101"

/** Bitwise XOR of [helloBits] and [randomBits]. */
private val xorBits: String = helloBits.zip(randomBits) { a, b -> if (a == b) '0' else '1' }.joinToString("")

/** XOR the ciphertext with the key again — recovers the data (XOR is its own inverse). */
private val recoveredBits: String = xorBits.zip(randomBits) { a, b -> if (a == b) '0' else '1' }.joinToString("")

/** First position where data and key are both 0 — the "same bits → 0" example (blue). */
private val xorBluePos: Int = helloBits.indices.first { helloBits[it] == '0' && randomBits[it] == '0' }

/** First position where data is 0 and key is 1 — the "different bits → 1" example (red). */
private val xorRedPos: Int = helloBits.indices.first { helloBits[it] == '0' && randomBits[it] == '1' }

/** First position where data is 1 and key is 0 — the "different bits → 1" example (yellow). */
private val xorYellow1Pos: Int = helloBits.indices.first { helloBits[it] == '1' && randomBits[it] == '0' }

/** First position where data is 1 and key is 1 — the "same bits → 0" example (yellow). */
private val xorYellow2Pos: Int = helloBits.indices.first { helloBits[it] == '1' && randomBits[it] == '1' }

/** Highlight styles for the XOR-explanation steps (7–9). */
private val highlightBlue: SpanStyle = SpanStyle(background = Color.Blue, color = Color.White)
private val highlightRed: SpanStyle = SpanStyle(background = Color.Red, color = Color.White)

/** Less-prominent yellow highlight (translucent) for the two "1-input" cases. */
private val mutedYellow: SpanStyle = SpanStyle(background = Color(0x66FFEB3B))

/** Step 7 — only the "same bits → 0" case (0⊕0). */
private val hlBlue: Map<Int, SpanStyle> = mapOf(xorBluePos to highlightBlue)

/** Step 8 — add the "different bits → 1" case (0⊕1). */
private val hlBlueRed: Map<Int, SpanStyle> = mapOf(xorBluePos to highlightBlue, xorRedPos to highlightRed)

/** Step 9 — add the two "1-input" cases (1⊕0, 1⊕1). */
private val xorHighlights: Map<Int, SpanStyle> = mapOf(
    xorBluePos to highlightBlue,
    xorRedPos to highlightRed,
    xorYellow1Pos to mutedYellow,
    xorYellow2Pos to mutedYellow
)

private val chipWidth: Dp = 96.dp

@Composable
private fun Chip(
    text: String,
    width: Dp = chipWidth,
    monospace: Boolean = false,
    emphasis: Boolean = false,
    fontSize: TextUnit = 16.sp
) {
    Box(
        modifier = Modifier
            .width(width)
            .padding(4.dp)
            .clip(RoundedCornerShape(10.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(vertical = 4.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = text,
            fontSize = fontSize,
            fontFamily = if (monospace) FontFamily.Monospace else null,
            fontWeight = if (emphasis) FontWeight.Bold else FontWeight.Normal,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

@Composable
private fun StageLabel(text: String, width: Dp = 72.dp) {
    Text(
        text = text,
        style = MaterialTheme.typography.labelLarge,
        color = MaterialTheme.colorScheme.onSurfaceVariant,
        modifier = Modifier.width(width)
    )
}

@Composable
private fun DownArrow(visible: Boolean) {
    AnimatedVisibility(
        visible = visible,
        enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow))
    ) {
        Icon(
            imageVector = Icons.Default.ArrowDownward,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.size(16.dp)
        )
    }
}

@Composable
private fun Stage(visible: Boolean, content: @Composable () -> Unit) {
    AnimatedVisibility(
        visible = visible,
        enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
            scaleIn(
                initialScale = 0.85f,
                animationSpec = spring(Spring.DampingRatioMediumBouncy, Spring.StiffnessMediumLow)
            ),
        content = { content() }
    )
}

/** A labelled, monospaced line of bits used in the XOR demonstration. */
@Composable
private fun BitsLine(
    label: String,
    bits: String,
    emphasized: Boolean = false,
    icon: ImageVector? = null,
    highlights: Map<Int, SpanStyle>? = null
) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        Box(modifier = Modifier.size(28.dp, 24.dp), contentAlignment = Alignment.Center) {
            if (icon != null) Icon(imageVector = icon, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp))
        }
        StageLabel(label, width = 104.dp)
        Text(
            text = buildAnnotatedString {
                bits.forEachIndexed { i, c ->
                    val hl = highlights?.get(i)
                    if (hl != null) {
                        withStyle(hl) { append(c) }
                    } else {
                        append(c)
                    }
                }
            },
            fontSize = 14.sp,
            fontFamily = FontFamily.Monospace,
            fontWeight = if (emphasized) FontWeight.Bold else FontWeight.Normal,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

val bits by Slide(stepCount = 11, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    val hl: Map<Int, SpanStyle>? = when (step) {
        7 -> hlBlue
        8 -> hlBlueRed
        9 -> xorHighlights
        else -> null
    }
    Box(modifier = Modifier.fillMaxSize()) {

        // Scene A — staged breakdown (string -> chars -> ASCII -> bit pills).
        // Fades out once we move to the merged/XOR view.
        androidx.compose.animation.AnimatedVisibility(
            visible = step < 4,
            modifier = Modifier.align(Alignment.Center),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
    Column(
        modifier = Modifier.padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            text = "It's all just bits",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.padding(bottom = 8.dp)
        )

        // Step 0 — the string
        Stage(visible = step >= 0) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                StageLabel("string")
                Chip(text = "\"$WORD\"", width = chipWidth * 5f, emphasis = true, fontSize = 20.sp)
            }
        }

        DownArrow(visible = step >= 1)

        // Step 1 — char array
        Stage(visible = step >= 1) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                StageLabel("chars")
                Row { chars.forEach { c -> Chip("'$c'") } }
            }
        }

        DownArrow(visible = step >= 2)

        // Step 2 — ASCII (base 10)
        Stage(visible = step >= 2) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                StageLabel("ASCII")
                Row { ascii.forEach { n -> Chip("$n", monospace = true) } }
            }
        }

        DownArrow(visible = step >= 3)

        // Step 3 — 8-bit binary
        Stage(visible = step >= 3) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                StageLabel("8 bits")
                Row { bitStrings.forEach { b -> Chip(b, monospace = true) } }
            }
        }
    }
        }

        // Scene B — the bits merged into one line at the top, then the XOR dance.
        // Slides up into place (towards the top) while the breakdown above fades out.
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 4,
            modifier = Modifier.align(Alignment.TopCenter),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
                slideInVertically(initialOffsetY = { it }),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            Column(
                modifier = Modifier.fillMaxSize().padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Step 4 — "hello" bits, now one continuous line at the top.
                BitsLine(label = "data", bits = helloBits, emphasized = true, highlights = hl)

                // Step 5 — a random line of the same length appears below.
                androidx.compose.animation.AnimatedVisibility(
                    visible = step >= 5,
                    enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
                        slideInVertically(initialOffsetY = { it / 2 })
                ) {
                    BitsLine(label = "XOR key", bits = randomBits, icon = Icons.Default.Key, highlights = hl)
                }

                // Step 6 — XOR the two lines into the ciphertext.
                androidx.compose.animation.AnimatedVisibility(
                    visible = step >= 6,
                    enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
                        slideInVertically(initialOffsetY = { it / 2 })
                ) {
                    BitsLine(label = "= enc", bits = xorBits, emphasized = true, icon = Icons.Default.Lock, highlights = hl)
                }

                // Steps 7–9 — what does XOR do? Reveal the four cases one at a time:
                //   step 7: 0⊕0=0 (blue)  →  step 8: +0⊕1=1 (red)  →  step 9: +1⊕0=1 & 1⊕1=0 (yellow).
                // These highlights apply only to steps 7–9; the next step returns to normal colours.

                // Step 10 — XOR the ciphertext with the SAME key again: the data is back.
                // (XOR is its own inverse — one operation, used for both encryption and decryption.)
                androidx.compose.animation.AnimatedVisibility(
                    visible = step >= 10,
                    enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)) +
                        slideInVertically(initialOffsetY = { it / 2 })
                ) {
                    BitsLine(label = "XOR key = data", bits = recoveredBits, emphasized = true, icon = Icons.Default.LockOpen)
                }
            }
        }
    }
}
